// WRONG: VSCode import in computer
import * as vscode from 'vscode';

export function createTaskGroupingComputer() {
  const icon = new vscode.ThemeIcon('task');  // Forbidden!
  return { icon };
}

// CORRECT: Pure TypeScript computer
export function createTaskGroupingComputer() {
  function groupByStatus(tasks: Task[]): Map<TaskStatus, Task[]> {
    // Pure computation, no VSCode API
    const grouped = new Map<TaskStatus, Task[]>();
    for (const task of tasks) {
      const list = grouped.get(task.status) || [];
      list.push(task);
      grouped.set(task.status, list);
    }
    return grouped;
  }

  return { groupByStatus };
}

// CORRECT: VSCode API in capability
import * as vscode from 'vscode';

export function createTerminalCapability() {
  let terminal: vscode.Terminal | undefined;

  function getOrCreateTerminal(name: string, cwd: string): vscode.Terminal {
    if (!terminal || !vscode.window.terminals.includes(terminal)) {
      terminal = vscode.window.createTerminal({ name, cwd });
    }
    return terminal;
  }

  function sendCommand(term: vscode.Terminal, command: string): void {
    term.sendText(command);
  }

  return { getOrCreateTerminal, sendCommand };
}

